),

srp_base AS (

    SELECT
        a.mri_session_id,
        a.route_id,
        CAST(a.doj AS DATE) AS doj,

        CASE
            WHEN CARDINALITY(FILTER(a.channel_exp_info, x -> x LIKE '%COMFORT_SCORE_AB:V0%')) > 0 THEN 'V0'
            WHEN CARDINALITY(FILTER(a.channel_exp_info, x -> x LIKE '%COMFORT_SCORE_AB:V1%')) > 0 THEN 'V1'
            WHEN CARDINALITY(FILTER(a.channel_exp_info, x -> x LIKE '%COMFORT_SCORE_AB:V2%')) > 0 THEN 'V2'
            ELSE NULL
        END AS variant,

        CAST(ROUND(rs.comfort_score, 1) AS DECIMAL(3,1)) AS comfort_score_band

    FROM user_interaction.search_route_details a

    INNER JOIN route_scores rs
        ON a.route_id = rs.route_id

    WHERE a.country = 'IND'
      AND a.os = 'Android'
      AND a.__time >= TIMESTAMP '2026-06-02 00:00:00'
      AND a.__time <  TIMESTAMP '2026-06-08 00:00:00'

      AND a.mri_session_id IS NOT NULL
      AND a.route_id IS NOT NULL
      AND a.doj IS NOT NULL
      AND a.src_id IS NOT NULL
      AND a.dest_id IS NOT NULL

      AND rs.comfort_score BETWEEN 8.0 AND 10.0

      AND (
            CARDINALITY(FILTER(a.channel_exp_info, x -> x LIKE '%COMFORT_SCORE_AB:V0%')) > 0
         OR CARDINALITY(FILTER(a.channel_exp_info, x -> x LIKE '%COMFORT_SCORE_AB:V1%')) > 0
         OR CARDINALITY(FILTER(a.channel_exp_info, x -> x LIKE '%COMFORT_SCORE_AB:V2%')) > 0
      )

      AND CONCAT(
            CAST(a.src_id AS VARCHAR),
            '-',
            CAST(a.dest_id AS VARCHAR)
          ) IN (
            '124-123',
            '123-124',
            '71425-122',
            '124-122',
            '733-70429',
            '733-807',
            '70429-733',
            '122-71425',
            '1377-733',
            '74694-74820',
            '74820-74694',
            '1439-733',
            '141-123',
            '248-122',
            '122-130',
            '122-124',
            '807-733',
            '124-130',
            '122-248',
            '641-130'
      )
),

seat_clicks AS (

    SELECT DISTINCT
        b.mri_session_id,
        b.route_id,
        CAST(b.doj AS DATE) AS doj

    FROM user_interaction.seat_layout_details b

    INNER JOIN route_scores rs
        ON b.route_id = rs.route_id

    WHERE b.country = 'IND'
      AND b.os = 'Android'
      AND b.__time >= TIMESTAMP '2026-06-02 00:00:00'
      AND b.__time <  TIMESTAMP '2026-06-08 00:00:00'

      AND b.mri_session_id IS NOT NULL
      AND b.route_id IS NOT NULL
      AND b.doj IS NOT NULL
      AND b.src_id IS NOT NULL
      AND b.dest_id IS NOT NULL

      AND rs.comfort_score BETWEEN 8.0 AND 10.0

      AND CONCAT(
            CAST(b.src_id AS VARCHAR),
            '-',
            CAST(b.dest_id AS VARCHAR)
          ) IN (
            '124-123',
            '123-124',
            '71425-122',
            '124-122',
            '733-70429',
            '733-807',
            '70429-733',
            '122-71425',
            '1377-733',
            '74694-74820',
            '74820-74694',
            '1439-733',
            '141-123',
            '248-122',
            '122-130',
            '122-124',
            '807-733',
            '124-130',
            '122-248',
            '641-130'
      )
),

joined AS (

    SELECT
        a.variant,
        a.comfort_score_band,
        b.route_id AS sl_route_id

    FROM srp_base a

    LEFT JOIN seat_clicks b
        ON a.mri_session_id = b.mri_session_id
       AND a.route_id = b.route_id
       AND a.doj = b.doj

    WHERE a.variant IS NOT NULL
)

SELECT
    variant,

    SUM(CASE WHEN comfort_score_band = CAST(8.0 AS DECIMAL(3,1)) THEN 1 ELSE 0 END) AS srp_loads_8_0,
    SUM(CASE WHEN comfort_score_band = CAST(8.0 AS DECIMAL(3,1)) AND sl_route_id IS NOT NULL THEN 1 ELSE 0 END) AS sl_loads_8_0,
    ROUND(100.0 * SUM(CASE WHEN comfort_score_band = CAST(8.0 AS DECIMAL(3,1)) AND sl_route_id IS NOT NULL THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN comfort_score_band = CAST(8.0 AS DECIMAL(3,1)) THEN 1 ELSE 0 END), 0), 3) AS ctr_pct_8_0,

    SUM(CASE WHEN comfort_score_band = CAST(8.1 AS DECIMAL(3,1)) THEN 1 ELSE 0 END) AS srp_loads_8_1,
    SUM(CASE WHEN comfort_score_band = CAST(8.1 AS DECIMAL(3,1)) AND sl_route_id IS NOT NULL THEN 1 ELSE 0 END) AS sl_loads_8_1,
    ROUND(100.0 * SUM(CASE WHEN comfort_score_band = CAST(8.1 AS DECIMAL(3,1)) AND sl_route_id IS NOT NULL THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN comfort_score_band = CAST(8.1 AS DECIMAL(3,1)) THEN 1 ELSE 0 END), 0), 3) AS ctr_pct_8_1,

