    ROUND(100.0 * SUM(CASE WHEN comfort_score_band = CAST(9.4 AS DECIMAL(3,1)) AND sl_route_id IS NOT NULL THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN comfort_score_band = CAST(9.4 AS DECIMAL(3,1)) THEN 1 ELSE 0 END), 0), 3) AS ctr_pct_9_4,

    SUM(CASE WHEN comfort_score_band = CAST(9.5 AS DECIMAL(3,1)) THEN 1 ELSE 0 END) AS srp_loads_9_5,
    SUM(CASE WHEN comfort_score_band = CAST(9.5 AS DECIMAL(3,1)) AND sl_route_id IS NOT NULL THEN 1 ELSE 0 END) AS sl_loads_9_5,
    ROUND(100.0 * SUM(CASE WHEN comfort_score_band = CAST(9.5 AS DECIMAL(3,1)) AND sl_route_id IS NOT NULL THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN comfort_score_band = CAST(9.5 AS DECIMAL(3,1)) THEN 1 ELSE 0 END), 0), 3) AS ctr_pct_9_5,

    SUM(CASE WHEN comfort_score_band = CAST(9.6 AS DECIMAL(3,1)) THEN 1 ELSE 0 END) AS srp_loads_9_6,
